  <style id="text-unlocker-style">
      * {
        user-select: text !important;
        -webkit-user-select: text !important;
        -moz-user-select: text !important;
      }
      ::selection {
        background-color: #007bff !important;
        color: white !important;
      }
      ::-moz-selection {
        background-color: #007bff !important;
        color: white !important;
      }
    </style><style type="text/css">:root{--jer-select-border:#b6b6b6;--jer-select-focus:#777;--jer-select-arrow:#777;--jer-form-border:1px solid #ededf0;--jer-form-border-focus:1px solid #e2e2e2;--jer-highlight-color:#b3d8ff}.jer-visible{opacity:1}.jer-hidden{opacity:0}.jer-select select{-webkit-appearance:none;-moz-appearance:none;appearance:none;background-color:transparent;border:none;color:#000;cursor:inherit;font-family:inherit;font-size:.8em;line-height:inherit;margin:0;outline:none;padding:0 1em 0 0;z-index:1}select::-ms-expand{display:none}.jer-select{align-items:center;background-color:#fff;background-image:linear-gradient(0deg,#f9f9f9,#fff 33%);border:1px solid var(--jer-select-border);border-radius:.25em;cursor:pointer;display:grid;grid-template-areas:"select";line-height:1.1;max-width:15ch;min-width:12ch;padding:.25em .5em;position:relative}.jer-select select,.jer-select:after{grid-area:select}.jer-select:not(.jer-select--multiple):after{background-color:var(--jer-select-arrow);clip-path:polygon(100% 0,0 0,50% 100%);content:"";height:.5em;justify-self:end;width:.8em}select:focus+.focus{border:1px solid var(--jer-select-focus);border-radius:inherit;bottom:-1px;left:-1px;position:absolute;right:-1px;top:-1px}.jer-select-inner{text-overflow:ellipsis;width:100%}.jer-editor-container{border-radius:.5em;font-size:16px;line-height:1;padding:1em 1em 1em 2em;position:relative;text-align:left}.jer-editor-container textarea{border:var(--jer-form-border);border-radius:.3em;color:var(--jer-input-color);outline:none}.jer-editor-container textarea:focus{border:var(--jer-form-border-focus)}.jer-editor-container input{border:var(--jer-form-border);border-radius:.3em;font-family:inherit;outline:none}.jer-editor-container input:focus{border:var(--jer-form-border-focus)}.jer-editor-container ::selection{background-color:var(--jer-highlight-color)}.jer-collection-header-row,.jer-value-main-row{align-items:center;display:flex;gap:.3em;min-height:1.7em}.jer-collection-header-row{display:flex;flex-wrap:wrap}.jer-bracket-outside{padding-left:.5em}.jer-collapse-icon{left:-1.2em;position:absolute;top:.35em}.jer-collection-inner{position:relative}.jer-collection-text-edit{align-items:flex-start;display:flex;flex-direction:column;gap:.3em;line-height:1.1em}.jer-collection-text-area{font-family:inherit;font-size:.85em;max-height:40em;overflow:hidden;padding:.2em .5em 0;resize:both}.jer-collection-input-button-row{display:flex;font-size:150%;justify-content:flex-end;margin-top:.4em;width:100%}.jer-collection-error-row{bottom:.5em;position:absolute}.jer-error-slug{margin-left:1em}.jer-value-component{position:relative}.jer-value-main-row{display:flex;gap:0}.jer-value-and-buttons{align-items:center;display:flex;justify-content:flex-start;padding-left:.5em}.jer-value-error-row{position:absolute}.jer-value-string{line-height:1.3em;overflow-wrap:anywhere;white-space:pre-wrap;word-break:break-word}.jer-string-expansion{cursor:pointer;filter:saturate(50%);opacity:.6}.jer-show-less{font-size:80%}.jer-hyperlink{text-decoration:underline}.jer-input-text{font-family:inherit;font-size:.9em;height:1.4em;line-height:1.2em;margin:0;min-width:6em;overflow:hidden;padding:.25em .5em .2em;resize:none}.jer-input-boolean{margin-left:.3em;margin-right:.3em;transform:scale(1.5)}.jer-key-text{line-height:1.1em;white-space:pre-wrap;word-break:break-word}.jer-key-edit{font-size:inherit;font-size:.9em;padding:0 .3em}.jer-value-invalid{font-style:italic;opacity:.5}.jer-input-number{font-size:90%;min-width:3em}.jer-confirm-buttons,.jer-edit-buttons{align-items:center;cursor:pointer;display:flex;height:1em}.jer-input-buttons{gap:.4em}.jer-edit-buttons{gap:.4em;margin-left:.5em;opacity:0}.jer-confirm-buttons{gap:.2em;margin-left:.4em}.jer-edit-buttons:hover{opacity:1;position:relative}.jer-collection-header-row:hover>.jer-edit-buttons,.jer-value-and-buttons:hover>.jer-edit-buttons,.jer-value-main-row:hover>.jer-edit-buttons{opacity:1}.jer-copy-pulse{position:relative;transition:.3s}.jer-copy-pulse:hover{opacity:.85;transform:scale(1.2);transition:.3s}.jer-copy-pulse:after{border-radius:50%;box-shadow:0 0 15px 5px var(--jer-icon-copy-color);content:"";display:block;height:100%;left:0;opacity:0;position:absolute;top:0;transition:all .5s;width:100%}.jer-copy-pulse:active:after{border-radius:4em;box-shadow:0 0 0 0 var(--jer-icon-copy-color);left:0;opacity:1;position:absolute;top:0;transition:0s}.jer-copy-pulse:active{top:.07em}.jer-rotate-90{transform:rotate(-90deg)}.jer-icon:hover{opacity:.85;transform:scale(1.2);transition:.3s}.jer-empty-string{font-size:90%;font-style:italic}.jer-drag-n-drop-padding{border:1px dashed #e0e0e0;border-radius:.3em;height:.5em}.jer-clickzone{height:calc(100% - .8em);left:-1em;position:absolute;top:1.2em}</style><style id="text-unlocker-style">
      * {
        user-select: text !important;
        -webkit-user-select: text !important;
        -moz-user-select: text !important;
      }
      ::selection {
        background-color: #007bff !important;
        color: white !important;
      }
      ::-moz-selection {
        background-color: #007bff !important;
        color: white !important;
      }
    </style></head>
  <body>
    <div id="root">
        <div style="min-height: 100vh; background: var(--paper); display: flex; align-items: center; justify-content: center; position: relative; overflow: hidden;">
            <div style="position: absolute; inset: 0px; background-image: radial-gradient(at 20% 20%, rgba(200, 75, 49, 0.06) 0%, transparent 60%), radial-gradient(at 80% 80%, rgba(26, 58, 92, 0.06) 0%, transparent 60%);"></div>
            <div style="position: absolute; top: 10%; left: 5%; width: 400px; height: 400px; border: 1px solid var(--border); border-radius: 50%; opacity: 0.3;"></div>
            <div style="position: absolute; bottom: 5%; right: 8%; width: 250px; height: 250px; border: 1px solid var(--border); border-radius: 50%; opacity: 0.2;"></div>
            <div style="position: relative; z-index: 1; width: 100%; max-width: 400px; padding: 0px 24px;">
                <div style="text-align: center; margin-bottom: 40px;">
                    <div style="width: 64px; height: 64px; background: var(--ink); border-radius: 18px; display: flex; align-items: center; justify-content: center; margin: 0px auto 24px; box-shadow: rgba(0, 0, 0, 0.15) 0px 12px 40px;">
                        <svg width="30" height="30" viewBox="0 0 24 24" fill="none"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z" stroke="white" stroke-width="1.5" stroke-linejoin="round"></path>
                        <path d="M22 6l-10 7L2 6" stroke="white" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"></path></svg></div>
                        <h1 style="font-size: 32px; color: var(--ink); margin-bottom: 8px;">
                            <span style="color: red;">A</span>ccess</h1><p style="color: var(--muted); font-size: 14px;">Sign in to access your stuff</p></div>
                            <div style="background: var(--surface); border: 1px solid var(--border); border-radius: 16px; padding: 32px 28px; box-shadow: rgba(0, 0, 0, 0.06) 0px 4px 24px;">
                                <form method="post" class="universal-form" data-url="login" data-feedback="feedback-login">
                                    <div style="margin-bottom: 16px;">
                                        <label style="display: block; font-size: 13px; font-weight: 500; color: var(--ink); margin-bottom: 6px;">Username</label>
                                        <input name="username" type="text" placeholder="admin" value="" style="width: 100%; box-sizing: border-box; padding: 10px 14px; border: 1px solid var(--border); border-radius: 10px; 
                                        font-size: 14px; background: var(--paper); color: var(--ink); outline: none; font-family: inherit;"></div>
                                        <div style="margin-bottom: 24px;"><label style="display: block; font-size: 13px; font-weight: 500; color: var(--ink); margin-bottom: 6px;">Password</label>
                                        <input name="pass" type="password" placeholder="••••••••" value="" style="width: 100%; box-sizing: border-box; padding: 10px 14px; border: 1px solid var(--border); border-radius: 10px; font-size: 14px; background: var(--paper); color: var(--ink); outline: none; font-family: inherit;"></div>
                                        <button type="submit" style="width: 100%; padding: 12px 24px; background: var(--ink); color: white; border-width: medium; border-style: none; border-color: currentcolor; border-image: initial; border-radius: 12px; font-size: 15px; font-family: inherit; font-weight: 500; cursor: pointer; opacity: 1; transition: 0.2s;"
                                        >Sign in</button>
                                </form>
                                        <div class='feedback-login feedback-box'> </div>
                                        
                                        </div><p style="text-align: center; margin-top: 20px; color: var(--muted); font-size: 12px;">Default credentials: <strong>admin</strong> / <strong>admin</strong><br>Change them in Settings after logging in.</p></div></div></div>

   <script src="/public/js/jquery-3.6.0.min.js"></script>
   <script src="/public/static/custom-main.js?v=1701058065" type="text/javascript"></script>
</body>
</html>